"use client"

import { useTheme } from "@/components/theme-provider"
import { siteAsset } from "@/lib/site-assets"

// Transparent lockups generated by scripts/brand/make_brand_assets.py (aspect ≈ 1.91:1),
// served from Object Storage (README → "Site assets").
const LOGO_BLACK = siteAsset("brand/logo-black.png")
const LOGO_WHITE = siteAsset("brand/logo-white.png")
const LOGO_ASPECT = 1650 / 862

interface DensifyLogomarkProps {
  className?: string
  /**
   * "navbar" — follows the app theme (black ink on light, white ink on dark).
   * "login"  — always white ink, for the dark auth screens.
   * Defaults to "navbar".
   */
  variant?: "navbar" | "login"
  /** Force an ink colour regardless of variant/theme (e.g. the marketing pages). */
  tone?: "black" | "white"
  /** Rendered height in px. Width scales automatically. */
  height?: number
}

export function DensifyLogomark({
  className = "",
  variant = "navbar",
  tone,
  height,
}: DensifyLogomarkProps) {
  const { theme } = useTheme()

  const ink = tone ?? (variant === "login" ? "white" : theme === "dark" ? "white" : "black")
  const displayHeight = height ?? (variant === "login" ? 96 : 48)

  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src={ink === "white" ? LOGO_WHITE : LOGO_BLACK}
      alt="Densify"
      height={displayHeight}
      width={Math.round(displayHeight * LOGO_ASPECT)}
      style={{ height: displayHeight, width: "auto", display: "block" }}
      className={className}
    />
  )
}
